def _clean_tags(tags: list[str]) -> list[str]:
    seen: dict[str, None] = {}
    for t in tags:
        t = t.strip()
        if t:
            seen.setdefault(t.lower(), None) or seen.__setitem__(t.lower(), t)
    # preserve first-seen original casing, deduped case-insensitively
    out: list[str] = []
    lowered: set[str] = set()
    for t in tags:
        t = t.strip()
        if t and t.lower() not in lowered:
            lowered.add(t.lower())
            out.append(t)
    return out

