:root {
  --bg: #f6f7f9;
  --card: #ffffff;
  --border: #e3e6ea;
  --text: #1c2430;
  --muted: #6b7684;
  --accent: #2563eb;
  --accent-fade: #eaf0fe;
  --danger: #dc2626;
  --radius: 10px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.5;
}

header {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding: 1rem 1.5rem;
  background: var(--card);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}

header h1 { font-size: 1.25rem; margin: 0; white-space: nowrap; }

#search {
  flex: 1;
  max-width: 520px;
  padding: 0.6rem 0.9rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 0.95rem;
}
#search:focus { outline: 2px solid var(--accent); border-color: var(--accent); }

main {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 1.5rem;
  max-width: 1100px;
  margin: 1.5rem auto;
  padding: 0 1.5rem;
}

#sidebar h2 {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
  margin: 1.5rem 0 0.5rem;
}

#tag-list { list-style: none; margin: 0; padding: 0; }
#tag-list li {
  display: flex;
  justify-content: space-between;
  padding: 0.35rem 0.6rem;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.9rem;
}
#tag-list li:hover { background: var(--accent-fade); }
#tag-list li.active { background: var(--accent); color: #fff; }
#tag-list li .count { color: var(--muted); }
#tag-list li.active .count { color: #dbe4ff; }

button {
  font: inherit;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--card);
  border-radius: 8px;
  padding: 0.55rem 0.9rem;
}
button:hover { border-color: var(--muted); }
button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}
button.primary:hover { background: #1d4ed8; }
#add-btn { width: 100%; }

#active-filter {
  margin-bottom: 1rem;
  font-size: 0.9rem;
  color: var(--muted);
}
#active-filter button {
  padding: 0.2rem 0.5rem;
  font-size: 0.8rem;
  margin-left: 0.5rem;
}

#bookmark-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 0.75rem; }

.bookmark {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.9rem 1.1rem;
}
.bookmark .top { display: flex; justify-content: space-between; gap: 1rem; }
.bookmark a.title {
  font-weight: 600;
  color: var(--text);
  text-decoration: none;
  font-size: 1.02rem;
}
.bookmark a.title:hover { color: var(--accent); text-decoration: underline; }
.bookmark .url {
  display: block;
  color: var(--muted);
  font-size: 0.82rem;
  margin-top: 0.15rem;
  word-break: break-all;
}
.bookmark .desc { margin: 0.5rem 0 0; font-size: 0.9rem; }
.bookmark .tags { margin-top: 0.6rem; display: flex; flex-wrap: wrap; gap: 0.4rem; }
.bookmark .tag {
  background: var(--accent-fade);
  color: var(--accent);
  padding: 0.1rem 0.55rem;
  border-radius: 999px;
  font-size: 0.78rem;
  cursor: pointer;
}
.bookmark .row-actions { display: flex; gap: 0.4rem; flex-shrink: 0; }
.bookmark .row-actions button { padding: 0.25rem 0.55rem; font-size: 0.8rem; }
.bookmark .row-actions .del:hover { color: var(--danger); border-color: var(--danger); }

.empty { color: var(--muted); text-align: center; margin-top: 3rem; }
.hidden { display: none !important; }

/* Dialog */
dialog {
  border: none;
  border-radius: 14px;
  padding: 1.5rem;
  width: min(480px, 92vw);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.25);
}
dialog::backdrop { background: rgba(15, 23, 42, 0.45); }
dialog h2 { margin: 0 0 1rem; }
dialog label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 0.9rem;
}
dialog .hint { font-weight: 400; color: var(--muted); }
dialog input, dialog textarea {
  width: 100%;
  margin-top: 0.3rem;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font: inherit;
  resize: vertical;
}
dialog input:focus, dialog textarea:focus {
  outline: 2px solid var(--accent);
  border-color: var(--accent);
}
dialog .actions { display: flex; justify-content: flex-end; gap: 0.6rem; margin-top: 0.5rem; }

@media (max-width: 720px) {
  main { grid-template-columns: 1fr; }
  header { flex-wrap: wrap; }
}

